    FOMOFE i := 0;
    FUKCHEFE i < m - 1 LOLO LEKFESH
        days := days + mdays[i];
        i := i + 1;
    EFUDU
    days := days + d - 1;
    FOMOFE w := days % 7;
    ZET w CHU
    0: LEKFESH EFOTU "Monday"; EFUDU
    ...
    EFUDU EFUDU
}
```
